function isPrima(n) {
  if (n < 2) return false;
  for (let i = 2; i * i <= n; i++) {
    if (n % i === 0) return false;
  }
  return true;
}

function fibonacci(n) {
  if (n <= 0) return [];
  let hasil = [0];
  if (n >= 2) hasil.push(1);
  for (let i = 2; i < n; i++) {
    hasil.push(hasil[i - 1] + hasil[i - 2]);
  }
  return hasil;
}

function tabelPerkalian(n) {
  let tabel = [];
  for (let i = 0; i < n; i++) {
    let baris = [];
    for (let j = 0; j < n; j++) {
      baris.push((i + 1) * (j + 1));
    }
    tabel.push(baris);
  }
  return tabel;
}

