function bubbleSort(arr) {
  let hasil = [...arr];
  for (let i = 0; i < hasil.length - 1; i++) {
    for (let j = 0; j < hasil.length - 1 - i; j++) {
      if (hasil[j] > hasil[j + 1]) {
        let temp = hasil[j];
        hasil[j] = hasil[j + 1];
        hasil[j + 1] = temp;
      }
    }
  }
  return hasil;
}

function sieveEratosthenes(n) {
  let isPrima = new Array(n + 1).fill(true);
  isPrima[0] = false;
  isPrima[1] = false;
  for (let i = 2; i * i <= n; i++) {
    if (isPrima[i]) {
      for (let j = i * i; j <= n; j += i) {
        isPrima[j] = false;
      }
    }
  }
  let hasil = [];
  for (let i = 2; i <= n; i++) {
    if (isPrima[i]) {
      hasil.push(i);
    }
  }
  return hasil;
}

function konversiBasis(n, basis) {
  if (n === 0) return '0';
  const digit = '0123456789abcdef';
  let hasil = '';
  while (n > 0) {
    hasil = digit[n % basis] + hasil;
    n = Math.floor(n / basis);
  }
  return hasil;
}

function jumlahDigitBerulang(n) {
  let langkah = 0;
  while (n >= 10) {
    n = String(n).split('').reduce((sum, d) => sum + Number(d), 0);
    langkah++;
  }
  return { langkah, nilai: n };
}

function pencarianBiner(arr, target) {
  let kiri = 0, kanan = arr.length - 1;
  while (kiri <= kanan) {
    let tengah = Math.floor((kiri + kanan) / 2);
    if (arr[tengah] === target) return tengah;
    if (arr[tengah] < target) kiri = tengah + 1;
    else kanan = tengah - 1;
  }
  return -1;
}

function sequenceCollatz(n) {
  let hasil = [n];
  while (n !== 1) {
    if (n % 2 === 0) {
      n = n / 2;
    } else {
      n = 3 * n + 1;
    }
    hasil.push(n);
  }
  return hasil;
}

