function terpanjangTanpaPengulangan(str) {
  let maxLen = 0, start = 0, charIndex = {};
  for (let i = 0; i < str.length; i++) {
    if (charIndex[str[i]] !== undefined && charIndex[str[i]] >= start) {
      start = charIndex[str[i]] + 1;
    }
    charIndex[str[i]] = i;
    maxLen = Math.max(maxLen, i - start + 1);
  }
  return maxLen;
}

